import org.json.JSONArray;
import org.json.JSONObject;
import org.joget.commons.util.LogUtil;
import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.FormRow;
import org.joget.apps.form.model.FormRowSet;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.sql.DataSource;

String username = "#currentUser.username#";
String diplomes_array = "";
String c_nature_bac = "";
LogUtil.info("Check", "Username: " + username);

private Connection getConnection() throws SQLException {
    DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
    return ds.getConnection();
}

try {
    Connection con = getConnection();
    PreparedStatement stmt = con.prepareStatement("SELECT c_autre_diplome, c_nature_bac FROM jwdb.app_fd_inscription_etud WHERE id LIKE ?");
    stmt.setString(1, username);
    ResultSet rs = stmt.executeQuery();

    if (rs.next()) {
        diplomes_array = rs.getString(1) != null ? rs.getString(1) : "";
        c_nature_bac = rs.getString(2) != null ? rs.getString(2) : "";
        LogUtil.info("Check", "diplomes_array: " + diplomes_array);
        LogUtil.info("Check", "c_nature_bac: " + c_nature_bac);
    } else {
        LogUtil.info("Check", "No records found for username: " + username);
    }

    rs.close();
    stmt.close();
    con.close();
} catch (SQLException e) {
    LogUtil.error("SQL Error", e, "Error executing SQL query");
    return new FormRowSet(); // Return empty FormRowSet on error
}

// Validate diplomes_array before parsing
String latestDiplome = "";
int latestAnneeFin = Integer.MIN_VALUE;
int latestNiveau = Integer.MIN_VALUE;
String latestStatut = "";

if (diplomes_array != null && !diplomes_array.trim().isEmpty()) {
    try {
        JSONArray jsonArray = new JSONArray(diplomes_array);

        for (int i = 0; i < jsonArray.length(); i++) {
            JSONObject jsonObject = jsonArray.getJSONObject(i);
            int anneeFin = 0;

            try {
                String anneeFinStr = jsonObject.optString("annee_fin", "0");
                anneeFin = anneeFinStr.isEmpty() ? 0 : Integer.parseInt(anneeFinStr);
            } catch (NumberFormatException e) {
                LogUtil.error("Error", e, "Invalid 'annee_fin' format: " + jsonObject.optString("annee_fin"));
                continue;
            }

            if (anneeFin > latestAnneeFin) {
                latestAnneeFin = anneeFin;
                latestDiplome = jsonObject.optString("diplome_obtenu", "");

                JSONArray parcoursArray;
                try {
                    parcoursArray = new JSONArray(jsonObject.optString("parcours", "[]"));
                } catch (Exception e) {
                    LogUtil.error("Error", e, "Invalid 'parcours' format: " + jsonObject.optString("parcours"));
                    continue;
                }

                for (int j = 0; j < parcoursArray.length(); j++) {
                    JSONObject parcoursObject = parcoursArray.getJSONObject(j);
                    String niveauStr = parcoursObject.optString("niveau", "0");
                    String statut = parcoursObject.optString("statut", "");
                    int niveau = Integer.MIN_VALUE;

                    try {
                        if (!niveauStr.isEmpty()) {
                            niveau = Integer.parseInt(niveauStr);
                        }
                    } catch (NumberFormatException e) {
                        LogUtil.error("Error", e, "Invalid 'niveau' format: " + niveauStr);
                        continue;
                    }

                    if (niveau > latestNiveau) {
                        latestNiveau = niveau;
                        latestStatut = statut;
                    }
                }
            }
        }
    } catch (Exception e) {
        LogUtil.error("JSON Error", e, "Error parsing diplomes_array: " + diplomes_array);
    }
} else {
    LogUtil.info("Check", "diplomes_array is empty or null");
}

LogUtil.info("Check", "Latest Diplome Obtenu: " + latestDiplome);
LogUtil.info("Check", "Latest Niveau Obtenu: " + latestNiveau);
LogUtil.info("Check", "Latest Statut Obtenu: " + latestStatut);

FormRowSet f = new FormRowSet();
f.setMultiRow(true);
FormRow r1 = new FormRow();
r1.put("latestDiplome", latestDiplome);
r1.put("latestNiveau", String.valueOf(latestNiveau));
r1.put("NatureBac", c_nature_bac);
f.add(r1);
return f;
